import{_ as e,o,c as r,a3 as l}from"./chunks/framework.C8xYrcAN.js";const u=JSON.parse('{"title":"mitmproxy 版教程 (MuMu 12 自动化)","description":"","frontmatter":{},"headers":[],"relativePath":"zh/guide/import_https/mitmproxy_mumu12.md","filePath":"zh/guide/import_https/mitmproxy_mumu12.md","lastUpdated":1793212313000}'),s={name:"zh/guide/import_https/mitmproxy_mumu12.md"};function n(a,t,d,g,i,c){return o(),r("div",null,[...t[0]||(t[0]=[l('<h1 id="mitmproxy-版教程-mumu-12-自动化" tabindex="-1">mitmproxy 版教程 (MuMu 12 自动化) <a class="header-anchor" href="#mitmproxy-版教程-mumu-12-自动化" aria-label="Permalink to &quot;mitmproxy 版教程 (MuMu 12 自动化)&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">特别声明</p><ol><li><strong>适用范围</strong>：以下说明仅适用于本页面介绍的“FGO 登录数据自动化抓取工具（含 run.bat 及 fgo_cap.py）”。</li><li><strong>服务器支持</strong>：本工具仅支持由 bilibili 运营的 <strong>国服 (简体中文)</strong> 和 <strong>台服 (繁体中文)</strong>。<strong>不支持</strong> 日服、韩服、美服。</li><li><strong>权属说明</strong>：本工具及其配套说明不代表本站或 Chaldea 项目组的立场。</li><li><strong>作者</strong>：本文由 <a href="https://github.com/vx13" target="_blank" rel="noreferrer">vx13</a> 编写。</li></ol></div><blockquote><p><strong>[ 法律声明与授权说明 ]</strong></p><ul><li><strong>项目独立性</strong>：本脚本及相关工具为独立开发的第三方辅助工具，其权属<strong>不属于</strong>《Fate/Grand Order》官方及其关联公司，亦<strong>不属于</strong> Chaldea 项目组。</li><li><strong>技术背景</strong>：本工具的核心逻辑、环境自检流程及本说明文档均借助 <strong>AI (人工智能)</strong> 协作设计与编写。</li><li><strong>版权许可</strong>：本工具<strong>未设任何版权限制</strong>。开发者欢迎并鼓励任何个人或组织对代码进行学习、修改、二次开发、功能扩展以及在社区内进行推广与分发。</li><li><strong>免责条款</strong>：本工具仅供技术交流与学习使用，旨在优化用户数据管理体验。开发者及 AI 协作方不对因使用本工具导致的任何直接或间接后果（如账号异常、隐私泄露等）承担法律责任。用户应在遵守当地法律法规及游戏服务协议的前提下使用。</li><li><strong>安全提示</strong>：抓取到的原始登录数据包含敏感凭据，<strong>请务必妥善保管，切勿发送给他人</strong>。</li></ul></blockquote><hr><h2 id="_0-工具下载" tabindex="-1">0. 工具下载 <a class="header-anchor" href="#_0-工具下载" aria-label="Permalink to &quot;0. 工具下载&quot;">​</a></h2><p>本工具已内置引擎（<code>mitmdump</code>），无需自行安装 Python 或 mitmproxy。</p><ul><li><strong>下载链接</strong>: <a href="https://disk.chaldea.center/s/r1FO" target="_blank" rel="noreferrer">站内分流</a></li></ul><hr><h2 id="_1-模拟器准备-mumu-12" tabindex="-1">1. 模拟器准备 (MuMu 12) <a class="header-anchor" href="#_1-模拟器准备-mumu-12" aria-label="Permalink to &quot;1. 模拟器准备 (MuMu 12)&quot;">​</a></h2><p>请务必完成以下设置并<strong>重启模拟器</strong>，否则脚本将无法执行底层操作：</p><table tabindex="0"><thead><tr><th style="text-align:left;">设置项</th><th style="text-align:left;">路径</th><th style="text-align:left;">设定值</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Root 权限</strong></td><td style="text-align:left;">[设备设置] - [其他]</td><td style="text-align:left;"><strong>开启</strong></td></tr><tr><td style="text-align:left;"><strong>系统盘可写</strong></td><td style="text-align:left;">[设备设置] - [磁盘]</td><td style="text-align:left;">选择 <strong>“可写系统盘”</strong></td></tr><tr><td style="text-align:left;"><strong>ADB 调试</strong></td><td style="text-align:left;">[设备设置] - [其他]</td><td style="text-align:left;">选择 <strong>“开启本地连接”</strong></td></tr></tbody></table><hr><h2 id="_2-运行与抓取流程" tabindex="-1">2. 运行与抓取流程 <a class="header-anchor" href="#_2-运行与抓取流程" aria-label="Permalink to &quot;2. 运行与抓取流程&quot;">​</a></h2><ol><li><strong>启动脚本</strong>：双击运行 <strong><code>run.bat</code></strong>，等待自检完成并提示 <code>[🚀] 正在监听...</code>。</li><li><strong>登录游戏</strong>：在模拟器中启动 FGO，点击进入游戏直到看到“地球仪”或“活动公告”。</li><li><strong>自动结束</strong>：捕获成功后窗口会提示 <code>[🎯] 捕获成功!</code>，脚本自动还原代理并退出，随后 <code>run.bat</code> <strong>停留在窗口等待按键</strong>，按任意键关闭即可。此时数据已存入剪贴板。</li></ol><div class="danger custom-block"><p class="custom-block-title">注意事项：中途退出与断网恢复</p><ul><li><strong>正确退出</strong>：若需手动停止，请务必在窗口内按 <strong><code>Ctrl + C</code></strong>。<strong>请勿</strong>直接点击窗口右上角的红色 [X] 关闭。</li><li><strong>断网修复</strong>：若因异常关闭导致模拟器无法上网，请<strong>再次运行 <code>run.bat</code> 并按 <code>Ctrl + C</code> 正常退出</strong>，或手动进入模拟器 [Wi-Fi设置] 将 [代理] 修改为 <strong>“无”</strong>。</li></ul></div><hr><h2 id="_3-导入-chaldea" tabindex="-1">3. 导入 Chaldea <a class="header-anchor" href="#_3-导入-chaldea" aria-label="Permalink to &quot;3. 导入 Chaldea&quot;">​</a></h2><ol><li>打开 <strong>Chaldea</strong> 客户端。</li><li>打开首页右下角 <strong>[导入]</strong> -&gt; <strong>[HTTPS抓包]</strong>，点击右上角导入按钮选择 <strong>[从剪切板]</strong> 即可完成。</li></ol><hr><h2 id="_4-脚本工作流程" tabindex="-1">4. 脚本工作流程 <a class="header-anchor" href="#_4-脚本工作流程" aria-label="Permalink to &quot;4. 脚本工作流程&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">步骤</th><th style="text-align:left;">执行逻辑</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>证书生成</strong></td><td style="text-align:left;">检索用户目录 CA 证书；若缺失，后台静默启动 <code>mitmdump</code> 生成证书。</td></tr><tr><td style="text-align:left;"><strong>ADB 查找</strong></td><td style="text-align:left;">通过检索 <code>MuMuNxDevice</code> 进程的文件路径，锁定并调用模拟器安装目录下的原生 <code>adb.exe</code>。</td></tr><tr><td style="text-align:left;"><strong>ADB 连接</strong></td><td style="text-align:left;">顺序执行 <code>kill-server</code> 与 <code>start-server</code> 重置服务；通过 <code>127.0.0.1:5555</code> 握手建立连接。</td></tr><tr><td style="text-align:left;"><strong>证书注入</strong></td><td style="text-align:left;">基于 <strong>MD5 散列值</strong>比对用户目录与模拟器系统证书内容；证书不存在或散列值不一致时上传覆盖。</td></tr><tr><td style="text-align:left;"><strong>代理配置</strong></td><td style="text-align:left;">自动解析宿主机局域网活跃 IP；通过 <code>adb shell settings</code> 接口将代理参数注入模拟器全局配置。</td></tr><tr><td style="text-align:left;"><strong>抓包分析</strong></td><td style="text-align:left;">匹配特定接口后缀 <code>_key=toplogin</code>；提取响应原始文本并通过系统管道写入 Windows 剪贴板。</td></tr><tr><td style="text-align:left;"><strong>代理清理</strong></td><td style="text-align:left;">监听捕获成功或 <code>Ctrl + C</code> 中断信号；将模拟器全局代理重置为关闭状态（<code>:0</code>）以还原网络环境。</td></tr></tbody></table>',21)])])}const m=e(s,[["render",n]]);export{u as __pageData,m as default};
